-- Zarban schema and curriculum seed for Cloudflare D1.
-- Learner and assessment history are intentionally not exported.

CREATE TABLE "skills" (
    "skill_id" TEXT NOT NULL PRIMARY KEY,
    "skill_name" TEXT NOT NULL,
    "grade_level" TEXT,
    "topic_area" TEXT,
    "difficulty_band" TEXT,
    "prerequisite_skill_ids" TEXT,
    "notes" TEXT
);

CREATE TABLE "questions" (
    "question_id" TEXT NOT NULL PRIMARY KEY,
    "question_text" TEXT NOT NULL,
    "question_type" TEXT,
    "word_problem_flag" BOOLEAN NOT NULL DEFAULT false,
    "equation_twin_id" TEXT,
    "primary_skill_id" TEXT,
    "secondary_skill_ids" TEXT,
    "grade_level" INTEGER,
    "difficulty_band" TEXT,
    "option_a" TEXT,
    "option_b" TEXT,
    "option_c" TEXT,
    "option_d" TEXT,
    "correct_option" TEXT,
    "irt_a" REAL NOT NULL DEFAULT 1.0,
    "irt_b" REAL NOT NULL DEFAULT 0.0,
    "irt_c" REAL NOT NULL DEFAULT 0.25,
    CONSTRAINT "questions_equation_twin_id_fkey" FOREIGN KEY ("equation_twin_id") REFERENCES "questions" ("question_id") ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT "questions_primary_skill_id_fkey" FOREIGN KEY ("primary_skill_id") REFERENCES "skills" ("skill_id") ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE "knowledge_graph" (
    "child_skill_id" TEXT NOT NULL,
    "parent_skill_id" TEXT NOT NULL,

    PRIMARY KEY ("child_skill_id", "parent_skill_id"),
    CONSTRAINT "knowledge_graph_child_skill_id_fkey" FOREIGN KEY ("child_skill_id") REFERENCES "skills" ("skill_id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "knowledge_graph_parent_skill_id_fkey" FOREIGN KEY ("parent_skill_id") REFERENCES "skills" ("skill_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "q_matrix" (
    "question_id" TEXT NOT NULL,
    "skill_id" TEXT NOT NULL,

    PRIMARY KEY ("question_id", "skill_id"),
    CONSTRAINT "q_matrix_question_id_fkey" FOREIGN KEY ("question_id") REFERENCES "questions" ("question_id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "q_matrix_skill_id_fkey" FOREIGN KEY ("skill_id") REFERENCES "skills" ("skill_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "answer_traps" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "question_id" TEXT NOT NULL,
    "option_label" TEXT NOT NULL,
    "option_text" TEXT,
    "trap_type" TEXT,
    "skill_gap_id" TEXT,
    "misconception" TEXT,
    "misconception_detail" TEXT,
    "remedial_action" TEXT,
    "remedial_skill_id" TEXT,
    "remedial_grade" INTEGER,
    CONSTRAINT "answer_traps_question_id_fkey" FOREIGN KEY ("question_id") REFERENCES "questions" ("question_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "question_dimensions" (
    "question_id" TEXT NOT NULL PRIMARY KEY,
    "dim_reading" BOOLEAN NOT NULL DEFAULT false,
    "dim_understanding" BOOLEAN NOT NULL DEFAULT false,
    "dim_application" BOOLEAN NOT NULL DEFAULT false,
    "dim_calculation" BOOLEAN NOT NULL DEFAULT false,
    "dim_retention" BOOLEAN NOT NULL DEFAULT false,
    "primary_dimension" TEXT,
    "word_eq_pair_id" TEXT,
    CONSTRAINT "question_dimensions_question_id_fkey" FOREIGN KEY ("question_id") REFERENCES "questions" ("question_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "students" (
    "student_id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT,
    "email" TEXT,
    "school" TEXT,
    "class_grade" INTEGER,
    "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "sessions" (
    "session_id" TEXT NOT NULL PRIMARY KEY,
    "student_id" TEXT NOT NULL,
    "selected_grade" INTEGER,
    "current_theta" REAL NOT NULL DEFAULT 0.0,
    "current_skill_id" TEXT,
    "current_grade" INTEGER,
    "current_difficulty" TEXT,
    "consecutive_failures" INTEGER NOT NULL DEFAULT 0,
    "status" TEXT NOT NULL DEFAULT 'in_progress',
    "started_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ended_at" DATETIME,
    "twin_probe_pending" BOOLEAN NOT NULL DEFAULT false,
    "twin_origin_question" TEXT,
    "pending_confirmation" BOOLEAN NOT NULL DEFAULT false,
    "max_questions" INTEGER NOT NULL DEFAULT 30,
    "bands_served" TEXT NOT NULL DEFAULT '',
    "consecutive_correct" INTEGER NOT NULL DEFAULT 0,
    "visited_skills" TEXT NOT NULL DEFAULT '',
    "return_skill_id" TEXT,
    "return_grade" INTEGER, "termination_reason" TEXT,
    CONSTRAINT "sessions_student_id_fkey" FOREIGN KEY ("student_id") REFERENCES "students" ("student_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "responses" (
    "response_id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "session_id" TEXT NOT NULL,
    "question_id" TEXT NOT NULL,
    "selected_option" TEXT,
    "is_correct" BOOLEAN,
    "trap_type" TEXT,
    "skill_gap_id" TEXT,
    "misconception" TEXT,
    "twin_probe" BOOLEAN NOT NULL DEFAULT false,
    "served_skill_id" TEXT,
    "served_grade" INTEGER,
    "served_difficulty" TEXT,
    "engine_decision" TEXT,
    "theta_after" REAL,
    "p_mastery_after" REAL,
    "response_time_ms" INTEGER,
    "responded_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "responses_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "sessions" ("session_id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "responses_question_id_fkey" FOREIGN KEY ("question_id") REFERENCES "questions" ("question_id") ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE TABLE "bkt_state" (
    "student_id" TEXT NOT NULL,
    "skill_id" TEXT NOT NULL,
    "p_mastery" REAL NOT NULL DEFAULT 0.10,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "last_updated" DATETIME,

    PRIMARY KEY ("student_id", "skill_id"),
    CONSTRAINT "bkt_state_student_id_fkey" FOREIGN KEY ("student_id") REFERENCES "students" ("student_id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "bkt_state_skill_id_fkey" FOREIGN KEY ("skill_id") REFERENCES "skills" ("skill_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "dimension_scores" (
    "session_id" TEXT NOT NULL PRIMARY KEY,
    "dim_reading" REAL,
    "dim_understanding" REAL,
    "dim_application" REAL,
    "dim_calculation" REAL,
    "dim_retention" REAL,
    CONSTRAINT "dimension_scores_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "sessions" ("session_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "traversal_events" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "session_id" TEXT NOT NULL,
    "from_skill_id" TEXT NOT NULL,
    "to_skill_id" TEXT NOT NULL,
    "from_grade" INTEGER,
    "to_grade" INTEGER,
    "reason" TEXT,
    "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "traversal_events_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "sessions" ("session_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "review_flags" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "session_id" TEXT NOT NULL,
    "skill_id" TEXT NOT NULL,
    "note" TEXT,
    "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "review_flags_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "sessions" ("session_id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "settings" (
    "key" TEXT NOT NULL PRIMARY KEY,
    "value" TEXT NOT NULL
);

CREATE TABLE "admin_users" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "email" TEXT NOT NULL,
    "name" TEXT,
    "password_hash" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'Viewer',
    "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);









CREATE UNIQUE INDEX "admin_users_email_key" ON "admin_users"("email");
CREATE UNIQUE INDEX "answer_traps_question_id_option_label_key" ON "answer_traps"("question_id", "option_label");
CREATE INDEX "knowledge_graph_parent_skill_id_idx" ON "knowledge_graph"("parent_skill_id");
CREATE INDEX "q_matrix_skill_id_idx" ON "q_matrix"("skill_id");
CREATE INDEX "questions_grade_level_difficulty_band_idx" ON "questions"("grade_level", "difficulty_band");
CREATE INDEX "questions_primary_skill_id_grade_level_difficulty_band_idx" ON "questions"("primary_skill_id", "grade_level", "difficulty_band");
CREATE INDEX "responses_session_id_idx" ON "responses"("session_id");
CREATE INDEX "sessions_student_id_idx" ON "sessions"("student_id");
CREATE UNIQUE INDEX "students_email_key" ON "students"("email");
CREATE INDEX "traversal_events_session_id_idx" ON "traversal_events"("session_id");
